"use strict";
// A package that lays one asking of node:fs behind another: what is asked twice is answered once.
const fs = require("node:fs");
const { lstatSync } = fs, answers = new Map();
fs.lstatSync = (path, ...more) => {
  if (more.length > 0) return lstatSync(path, ...more);
  const before = answers.get(path);
  if (before) return before;
  answers.set(path, lstatSync(path));
  return fs.lstatSync(path);
};
const first = require("fs").lstatSync(".");
module.exports = { ok: [first === fs.lstatSync("."), first.isDirectory(), answers.size, typeof fs.lstatSync(".", { bigint: true }).size].join() };
